import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Inspect{public static void main(String[]a)throws Exception{try(ZipFile z=new ZipFile(a[0])){int checked=0;for(String name:List.of("EntityRenderCaptureHandler","ClientMobTextureCache","ClientRagdollRenderer")){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("com/raiiiden/ragdollified/client/"+name+".class")).readAllBytes()).accept(c,0);for(MethodNode m:c.methods){if(name.equals("EntityRenderCaptureHandler")){for(var n:m.instructions)if(n instanceof MethodInsnNode i){if(i.owner.equals("dev/zomboid/gore/Capture21")&&i.name.equals("model"))checked++;}}if(name.equals("ClientRagdollRenderer")&&m.name.equals("getBaseMobTexture")){int count=0;for(var n:m.instructions)if(n instanceof MethodInsnNode i&&i.name.equals("setCachedTexture"))count++;if(count!=1)throw new AssertionError("fallback still cached");checked++;}if(name.equals("ClientMobTextureCache")&&m.name.equals("cleanup")){for(var n:m.instructions)if(n instanceof MethodInsnNode i&&i.name.equals("clear"))throw new AssertionError("whole cache cleared");checked++;}}}if(checked!=3)throw new AssertionError(checked);}System.out.println("PRODUCTION_RAGDOLL_BYTECODE_TEXTURE_MODEL_AND_CACHE_GUARDS=PASS");}}
